definitions.verbatim:
def Refines {t} (P Q : SourcePartition t) : Prop :=
  ∀ u v x y, LeafAt t u x → LeafAt t v y →
    P.owner u = P.owner v → Q.owner u = Q.owner v

def LocalMinimum (t s : Tree) (m : Nat) : Prop :=
  (∃ F, agreement t s F=true ∧ F.length-1=m) ∧
    ∀ F, agreement t s F=true → m≤F.length-1

def meterColorLabel (T : Tree) (v : RMAF.Vertex) (x : Nat) : Charged Nat :=
  let a := meterLeafList [x] T
  let b := meterRegion v (a.value.headD [])
  ⟨b.value,a.work+b.work+3⟩
